#!/usr/bin/env python3
import argparse,collections,json,pathlib,hashlib
import numpy as np
ap=argparse.ArgumentParser();ap.add_argument('--audit',required=True);ap.add_argument('--out',required=True);a=ap.parse_args();audit=json.loads(pathlib.Path(a.audit).read_text());records=audit['records'];summary={}
for case in ('can','bowl'):
 rs=[r for r in records if r['case']==case];good=[r for r in rs if r['success']];metrics={}
 for key in ['bilateral_hold','penetration_peak_mm','max_step_disp_mm','recipient_shift_mm','min_horizontal_clearance_mm','hold_relative_slip_mm','post_drift_mm']:
  vals=[r[key] for r in good if r[key] is not None];metrics[key]={'min':min(vals),'max':max(vals)} if vals else None
 centers=[np.mean(np.array(r['initial_object_bbox']),axis=0) for r in rs];extents=[np.diff(np.array(r['initial_object_bbox']),axis=0)[0] for r in rs]
 summary[case]={'success':len(good),'total':len(rs),'acceptance':audit['pass'] and len(rs)==10 and len(good)>=9,'unique_initial_states':len({r['initial_state_sha256'] for r in rs}),'target_center_range_m':[np.min(centers,0),np.max(centers,0)],'target_bbox_size_range_mm':[np.min(extents,0)*1000,np.max(extents,0)*1000],'mass_kg':sorted({r['mass_kg'] for r in rs}),'metrics_successes_only':metrics,'failure_stages':dict(collections.Counter(r['failure']['stage'] if r['failure'] else 'gate_only' for r in rs if not r['success'])),'force_mean_range_N':[np.min([r['hold_force_mean_N'] for r in good],0),np.max([r['hold_force_mean_N'] for r in good],0)] if good else None,'max_hold_force_balance_norm_N':max((np.linalg.norm(r['hold_force_balance_mean_N']) for r in good),default=None),'max_unsupported_hold_contact_N':max((r['hold_other_force_peak_N'] for r in good),default=None),'unsafe_contact_samples':sum(r['unsafe_contact_samples'] for r in rs),'robot_nontarget_contacts':sum(r['robot_nontarget_contacts'] for r in rs)}
out={'version':'summarize_real_object_r1','audit':str(a.audit),'audit_sha256':hashlib.sha256(pathlib.Path(a.audit).read_bytes()).hexdigest(),'evidence_pass':audit['pass'],'task_scope_pass':all(s['acceptance'] for s in summary.values()),'cases':summary,'total_physics_samples':sum(r['physics_samples'] for r in records),'limits':['Two native tasks only; not the 10x20 Spatial final acceptance','Scripted teacher, not pi0.5 or training dataset','Original simulated masses and collision models; no real hardware validation']}
with pathlib.Path(a.out).open('x') as f:json.dump(out,f,ensure_ascii=False,indent=2,default=lambda x:x.tolist() if isinstance(x,np.ndarray) else x.item())
print(json.dumps(out,ensure_ascii=False,indent=2,default=lambda x:x.tolist() if isinstance(x,np.ndarray) else x.item()))
